                ['date_en' => '1515', 'date_ku' => '1515', 'date_ar' => '1515', 'title_en' => 'The Ottomans', 'title_ku' => 'عوسمانییەکان', 'title_ar' => 'العثمانيون', 'text_en' => 'Selim I takes the city; the walls stop being a defence and become a frame.', 'text_ku' => 'سەلیمی یەکەم شارەکە دەگرێت؛ شووراکان لە بەرگریبوون دەوەستن و دەبنە چوارچێوە.', 'text_ar' => 'يأخذ سليم الأول المدينة؛ وتكفّ الأسوار عن كونها دفاعاً وتصبح إطاراً.'],
                ['date_en' => '2000–2007', 'date_ku' => '2000–2007', 'date_ar' => '2000–2007', 'title_en' => 'Cleared and cleaned', 'title_ku' => 'پاککراوە و خاوێنکراوە', 'title_ar' => 'أُزيل ما حولها ونُظّفت', 'text_en' => 'Buildings leaning on the walls are removed and a park laid out along the outer face.', 'text_ku' => 'ئەو بینایانەی پاڵیان بە شووراکانەوە دابوو لادەبرێن و پارکێک بە درێژایی ڕووی دەرەوەدا دادەنرێت.', 'text_ar' => 'تُزال المباني المتكئة على الأسوار ويُقام متنزه على امتداد الوجه الخارجي.'],
                ['date_en' => '4 July 2015', 'date_ku' => '4ی تەمووزی 2015', 'date_ar' => '4 تموز 2015', 'title_en' => 'World Heritage', 'title_ku' => 'میراتی جیهانی', 'title_ar' => 'التراث العالمي', 'text_en' => 'The fortress and the Hevsel Gardens are inscribed together, as one cultural landscape.', 'text_ku' => 'قەڵاکە و باخچەکانی هەڤسێل پێکەوە، وەک یەک دیمەنی کولتووری، تۆمار دەکرێن.', 'text_ar' => 'تُدرج القلعة وبساتين هفسل معاً، بوصفهما مشهداً ثقافياً واحداً.'],
            ],
